arguments.query:
SELECT COUNT(*) AS rental_count FROM rental;
SELECT COUNT(*) AS payment_count, ROUND(SUM(amount), 2) AS total_amount, ROUND(AVG(amount), 2) AS average_amount FROM payment;
SELECT c.name AS category_name, COUNT(DISTINCT r.rental_id) AS rental_count
FROM rental AS r
JOIN inventory AS i ON i.inventory_id = r.inventory_id
JOIN film_category AS fc ON fc.film_id = i.film_id
JOIN category AS c ON c.category_id = fc.category_id
GROUP BY c.category_id, c.name
ORDER BY rental_count DESC, category_name ASC
LIMIT 3;

